function listPage(tasks, query) {
	const fail = (code, message) => ({ status: 400, body: { error: { code, message } } });
	const rawLimit = query.get("limit") ?? "25";
	const limit = Number(rawLimit);
	if (!/^\d+$/.test(rawLimit) || !Number.isInteger(limit) || limit < 1 || limit > 50) {
		return fail("invalid_limit", "limit must be an integer between 1 and 50");
	}
	const status = query.get("status");
	if (status !== null && status !== "open" && status !== "done") {
		return fail("invalid_status", "status must be open or done");
	}
	let after = null;
	if (query.has("cursor")) {
		try {
			const cursor = query.get("cursor");
			const decoded = Buffer.from(cursor, "base64url").toString("utf8");
			const value = JSON.parse(decoded);
			if (!cursor || Buffer.from(decoded).toString("base64url") !== cursor ||
				!value || Object.keys(value).sort().join(",") !== "id,status" ||
				typeof value.id !== "string" || !value.id || value.status !== status) {
				throw new Error("invalid cursor");
			}
			after = value.id;
		} catch {
			return fail("invalid_cursor", "cursor is invalid for this query");
		}
	}
	const matching = [...tasks]
		.filter(task => !task.deleted_at && (status === null || task.status === status) &&
			(after === null || task.id > after))
		.sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	const items = matching.slice(0, limit).map(task => ({ ...task }));
	const next_cursor = matching.length > limit
		? Buffer.from(JSON.stringify({ id: items.at(-1).id, status })).toString("base64url")
		: null;
	return { status: 200, body: { items, next_cursor } };
}
